contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(amount == 0);

        c.getTokens{value: 0}(); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(address(this)) == 2500e18 && c.blacklist(address(this)));
    }

    receive() external payable {}
}

